<?php
require_once __DIR__.'/_bootstrap.php'; $method=strtoupper($_SERVER['REQUEST_METHOD']??'GET'); if ($method==='POST') { $b=requestBody(); if (strtolower((string)($b['action']??''))!=='logout') jsonResponse(400,['ok'=>false,'error'=>'Invalid action.']); clearSession(); jsonResponse(200,['ok'=>true,'user'=>null]); } requireMethod('GET'); $u=currentUser(); if (!$u) jsonResponse(200,['ok'=>true,'user'=>null]); try { $s=db()->prepare('SELECT id,username FROM public.users WHERE id=:id LIMIT 1'); $s->execute(['id'=>$u['id']]); $r=$s->fetch(); if (!$r) { clearSession(); jsonResponse(200,['ok'=>true,'user'=>null]); } jsonResponse(200,['ok'=>true,'user'=>['id'=>(string)$r['id'],'username'=>$r['username']]]); } catch(Throwable $e) { error_log('[Bastion me] '.$e->getMessage()); jsonResponse(500,['ok'=>false,'error'=>'Could not check the current session.']); }
